  calcularTotalItems(): void {
    this.totalItems = this.getRegistrosFiltrados().length;
  }

  cambiarPagina(pagina: number): void {
    this.paginaActual = pagina;
  }

  get totalPaginas(): number {
    return Math.ceil(this.totalItems / this.itemsPorPagina);
  }

  get registrosPaginados(): any[] {
    const registros = this.getRegistrosFiltrados();
    const inicio = (this.paginaActual - 1) * this.itemsPorPagina;
    const fin = inicio + this.itemsPorPagina;
    return registros.slice(inicio, fin);
  }

  getPaginationArray(): (number | string)[] {
    const total = this.totalPaginas;
    const current = this.paginaActual;
    const delta = 2;
    const range: number[] = [];
    const rangeWithDots: (number | string)[] = [];

    for (let i = 1; i <= total; i++) {
      if (i === 1 || i === total || (i >= current - delta && i <= current + delta)) {
        range.push(i);
      }
    }

    let prev = 0;
    for (const i of range) {
      if (prev !== 0) {
        if (i - prev === 2) {
          rangeWithDots.push(prev + 1);
        } else if (i - prev !== 1) {
          rangeWithDots.push('...');
        }
      }
      rangeWithDots.push(i);
      prev = i;
    }

    return rangeWithDots;
  }

  cambiarPaginaNumero(pagina: number | string): void {
    if (typeof pagina === 'number') {
      this.paginaActual = pagina;
    }
  }

